    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then IDENTIFICATION_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then IDENTIFICATION_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then IDENTIFICATION_NUMBER end)) as IDENTIFICATION_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PAN_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAN_NUMBER end)) as PAN_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then AADHAAR_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AADHAAR_NUMBER end)) as AADHAAR_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EIA_NUMBER end) as EIA_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then GSTIN end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GSTIN end)) as GSTIN,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGE_PROOF_TYPE end) as AGE_PROOF_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PASSPORT_NUMBER end) as PASSPORT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AADHAAR_VERIFICATION_STATUS end) as AADHAAR_VERIFICATION_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAN_VERIFICATION_STATUS end) as PAN_VERIFICATION_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TAN_NUMBER end) as TAN_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then GST_REGISTRATION_STATUS end) as GST_REGISTRATION_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when IDENTIFICATION_NUMBER is not null or PAN_NUMBER is not null or AADHAAR_NUMBER is not null or EIA_NUMBER is not null or GSTIN is not null or AGE_PROOF_TYPE is not null or PASSPORT_NUMBER is not null or AADHAAR_VERIFICATION_STATUS is not null or PAN_VERIFICATION_STATUS is not null or TAN_NUMBER is not null or GST_REGISTRATION_STATUS is not null
                     then md5(upper(coalesce(cast(IDENTIFICATION_NUMBER as varchar), '') || '|' || coalesce(cast(PAN_NUMBER as varchar), '') || '|' || coalesce(cast(AADHAAR_NUMBER as varchar), '') || '|' || coalesce(cast(EIA_NUMBER as varchar), '') || '|' || coalesce(cast(GSTIN as varchar), '') || '|' || coalesce(cast(AGE_PROOF_TYPE as varchar), '') || '|' || coalesce(cast(PASSPORT_NUMBER as varchar), '') || '|' || coalesce(cast(AADHAAR_VERIFICATION_STATUS as varchar), '') || '|' || coalesce(cast(PAN_VERIFICATION_STATUS as varchar), '') || '|' || coalesce(cast(TAN_NUMBER as varchar), '') || '|' || coalesce(cast(GST_REGISTRATION_STATUS as varchar), '')))
                end as SAT_PARTY_IDENTIFICATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_IDENTIFICATION_HASHDIFF is not null
